<?php
namespace Tests\Feature;use App\Models\TvBroadcast;use App\Models\TvChannel;use App\Models\Video;use App\Models\VideoClip;use App\Services\TvDashboardService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class TvConsolidationTest extends TestCase{use RefreshDatabase;
 public function test_dashboard_consolidates_live_video_and_render_status():void{$channel=TvChannel::create(['name'=>'TV','slug'=>'tv','is_active'=>true]);TvBroadcast::create(['tv_channel_id'=>$channel->id,'title'=>'Ao vivo','provider'=>'youtube','playback_url'=>'https://youtube.com/live/abc123XYZ','status'=>'live','force_live'=>true]);$video=Video::create(['title'=>'Vídeo','slug'=>'video','provider'=>'file','video_path'=>'videos/a.mp4','is_published'=>true,'published_at'=>now()]);VideoClip::create(['video_id'=>$video->id,'title'=>'Short','status'=>'queued','aspect_ratio'=>'9:16','starts_at_ms'=>0,'ends_at_ms'=>15000]);$data=app(TvDashboardService::class)->data();$this->assertSame(1,$data['stats']['live_now']);$this->assertSame(1,$data['stats']['published_videos']);$this->assertSame(1,$data['stats']['clips_queued']);$this->get('/tv')->assertOk()->assertSee('Ao vivo');$this->get('/videos')->assertOk()->assertSee('Vídeo');}
}
